#include <vulkan/vulkan.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
static double now(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec*1000.0+t.tv_nsec/1e6; }
#define VK(call) do { VkResult r=(call); if(r) { fprintf(stderr,"%s: %d\n",#call,r); return 1; } } while(0)
int main(int argc,char **argv) {
 if(argc!=2) return 2;
 VkApplicationInfo app={.sType=VK_STRUCTURE_TYPE_APPLICATION_INFO,.pApplicationName="coverage-probe",.apiVersion=VK_API_VERSION_1_3};
 VkInstanceCreateInfo ic={.sType=VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO,.pApplicationInfo=&app};VkInstance instance;VK(vkCreateInstance(&ic,0,&instance));
 uint32_t n=1;VkPhysicalDevice physical;VK(vkEnumeratePhysicalDevices(instance,&n,&physical));
 uint32_t qn=0;vkGetPhysicalDeviceQueueFamilyProperties(physical,&qn,0);VkQueueFamilyProperties *qs=calloc(qn,sizeof(*qs));vkGetPhysicalDeviceQueueFamilyProperties(physical,&qn,qs);
 uint32_t queue=0;while(!(qs[queue].queueFlags&VK_QUEUE_GRAPHICS_BIT))queue++;free(qs);
 float priority=1;VkDeviceQueueCreateInfo qc={.sType=VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO,.queueFamilyIndex=queue,.queueCount=1,.pQueuePriorities=&priority};
 VkPhysicalDeviceVulkan13Features features={.sType=VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_3_FEATURES,.shaderZeroInitializeWorkgroupMemory=VK_TRUE};
 VkDeviceCreateInfo dc={.sType=VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO,.pNext=&features,.queueCreateInfoCount=1,.pQueueCreateInfos=&qc};VkDevice device;VK(vkCreateDevice(physical,&dc,0,&device));
 FILE *f=fopen(argv[1],"rb");if(!f)return 3;fseek(f,0,SEEK_END);size_t size=ftell(f);rewind(f);void *code=malloc(size);if(fread(code,1,size,f)!=size)return 4;fclose(f);
 VkShaderModuleCreateInfo sc={.sType=VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,.codeSize=size,.pCode=code};VkShaderModule shader;VK(vkCreateShaderModule(device,&sc,0,&shader));free(code);
 VkDescriptorSetLayout layouts[2];
 for(int group=0;group<2;group++) {
  VkDescriptorSetLayoutBinding bindings[6]={0};int count=group?4:6;
  for(int i=0;i<count;i++) bindings[i]=(VkDescriptorSetLayoutBinding){.binding=i,.descriptorType=group||i==3?VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE:i==0?VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC:VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,.descriptorCount=1,.stageFlags=!group&&(i==0||i==1||i==4)?VK_SHADER_STAGE_VERTEX_BIT|VK_SHADER_STAGE_FRAGMENT_BIT:VK_SHADER_STAGE_FRAGMENT_BIT};
  VkDescriptorSetLayoutCreateInfo bc={.sType=VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO,.bindingCount=count,.pBindings=bindings};VK(vkCreateDescriptorSetLayout(device,&bc,0,&layouts[group]));
 }
 VkPipelineLayoutCreateInfo lc={.sType=VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO,.setLayoutCount=2,.pSetLayouts=layouts};VkPipelineLayout pipeline_layout;VK(vkCreatePipelineLayout(device,&lc,0,&pipeline_layout));
 VkAttachmentDescription attachment={.format=VK_FORMAT_R16G16B16A16_SFLOAT,.samples=VK_SAMPLE_COUNT_1_BIT,.loadOp=VK_ATTACHMENT_LOAD_OP_LOAD,.storeOp=VK_ATTACHMENT_STORE_OP_STORE,.initialLayout=VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL,.finalLayout=VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL};
 VkAttachmentReference color={.attachment=0,.layout=VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL};
 VkSubpassDescription subpass={.pipelineBindPoint=VK_PIPELINE_BIND_POINT_GRAPHICS,.colorAttachmentCount=1,.pColorAttachments=&color};
 VkRenderPassCreateInfo rc={.sType=VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO,.attachmentCount=1,.pAttachments=&attachment,.subpassCount=1,.pSubpasses=&subpass};VkRenderPass renderpass;VK(vkCreateRenderPass(device,&rc,0,&renderpass));
 VkPipelineShaderStageCreateInfo stages[2]={
 {.sType=VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO,.stage=VK_SHADER_STAGE_VERTEX_BIT,.module=shader,.pName="vs_main"},
 {.sType=VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO,.stage=VK_SHADER_STAGE_FRAGMENT_BIT,.module=shader,.pName="fs_main"}};
 VkPipelineVertexInputStateCreateInfo vi={.sType=VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO};
 VkPipelineInputAssemblyStateCreateInfo ia={.sType=VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO,.topology=VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST};
 VkViewport viewport={.width=1,.height=1,.maxDepth=1};VkRect2D scissor={.extent={1,1}};
 VkPipelineViewportStateCreateInfo vp={.sType=VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO,.viewportCount=1,.pViewports=&viewport,.scissorCount=1,.pScissors=&scissor};
 VkPipelineRasterizationStateCreateInfo rs={.sType=VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO,.polygonMode=VK_POLYGON_MODE_FILL,.cullMode=VK_CULL_MODE_NONE,.frontFace=VK_FRONT_FACE_COUNTER_CLOCKWISE,.lineWidth=1};
 VkPipelineMultisampleStateCreateInfo ms={.sType=VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO,.rasterizationSamples=VK_SAMPLE_COUNT_1_BIT};
 VkPipelineColorBlendAttachmentState ba={.blendEnable=VK_TRUE,.srcColorBlendFactor=VK_BLEND_FACTOR_ONE,.dstColorBlendFactor=VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA,.colorBlendOp=VK_BLEND_OP_ADD,.srcAlphaBlendFactor=VK_BLEND_FACTOR_ONE,.dstAlphaBlendFactor=VK_BLEND_FACTOR_ONE_MINUS_SRC_ALPHA,.alphaBlendOp=VK_BLEND_OP_ADD,.colorWriteMask=15};
 VkPipelineColorBlendStateCreateInfo bs={.sType=VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO,.attachmentCount=1,.pAttachments=&ba};
 VkGraphicsPipelineCreateInfo pc={.sType=VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO,.stageCount=2,.pStages=stages,.pVertexInputState=&vi,.pInputAssemblyState=&ia,.pViewportState=&vp,.pRasterizationState=&rs,.pMultisampleState=&ms,.pColorBlendState=&bs,.layout=pipeline_layout,.renderPass=renderpass};
 double start=now();VkPipeline pipeline;VK(vkCreateGraphicsPipelines(device,VK_NULL_HANDLE,1,&pc,0,&pipeline));double elapsed=now()-start;
 printf("{\"pipeline_ms\":%.6f}\n",elapsed);
 vkDestroyPipeline(device,pipeline,0);vkDestroyRenderPass(device,renderpass,0);
 vkDestroyPipelineLayout(device,pipeline_layout,0);vkDestroyDescriptorSetLayout(device,layouts[0],0);vkDestroyDescriptorSetLayout(device,layouts[1],0);vkDestroyShaderModule(device,shader,0);vkDestroyDevice(device,0);vkDestroyInstance(instance,0);return 0;
}
